import type { Localized } from "./types";

export interface CatalogProduct {
  image: string;
  alt: string;
  name: string;
  /** Stable id, shared across all 4 languages, used by /kategori-*.html and /urun-*.html query-param routing. */
  slug: string;
  /** Real weight in kg where a confident match to an old detail page exists; null otherwise (not fabricated). */
  weightKg: number | null;
  /** Real wheel/caster count where known; null otherwise. */
  wheelCount: number | null;
  /** null for the handful of real products whose source catalog page omits this dimension. */
  widthCm: number | null;
  lengthCm: number | null;
  heightCm: number | null;
  volumeLabel: string;
  material: string;
  origin: string;
  /** null for the handful of real products with no listed color options. */
  colors: string | null;
  tags: string[];
}

export interface CatalogFamily {
  slug: string;
  name: string;
  description: string;
  products: CatalogProduct[];
}

export interface CatalogCertificate {
  title: string;
  subtitle: string;
  certNo: string;
}

export interface CatalogContent {
  pageTitle: string;
  breadcrumbHome: string;
  breadcrumbCurrent: string;
  heroLead: string;
  stats: { value: string; label: string }[];
  families: CatalogFamily[];
  certSectionTitle: string;
  certificates: CatalogCertificate[];
  certNote: string;
  ctaTitle: string;
  ctaBody: string;
  ctaButton: string;
}

